const pptxgen = require("pptxgenjs"); // Import pptxgenjs module

// Get the PowerPoint generation script from GPT-4o output
const scriptContent = $json["query"];

// Initialize pptxgenjs
let pptx = new pptxgen();

// Execute the script to create slides
try {
    eval(scriptContent); // Runs the dynamically generated PowerPoint creation script
} catch (error) {
    throw new Error("Error executing script: " + error.message);
}

// Define the file path for saving the generated PowerPoint in n8n Docker
const filePath = "/files/generated_presentation.pptx";

// Save the PowerPoint file and return the file path
return pptx.writeFile({ filePath }).then(() => {
    return [{ json: { filePath } }];
}).catch(error => {
    throw new Error("Error saving PowerPoint file: " + error.message);
});
